const [pr, commits] = await Promise.all([
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get" }),
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_commits", perPage: 10 })
]);
return { number: pr.number, title: pr.title, state: pr.state, html_url: pr.html_url, base: pr.base?.ref, head: pr.head?.ref, commits: (commits || []).map ? (commits || []).map(c => ({ sha: c.sha, message: c.commit?.message?.split("\n")[0] })) : commits };

const [pr, commits] = await Promise.all([
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get" }),
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_commits", perPage: 10 })
]);
return { number: pr.number, title: pr.title, state: pr.state, html_url: pr.html_url, base: pr.base?.ref, head: pr.head?.ref, commits: (commits || []).map ? (commits || []).map(c => ({ sha: c.sha, message: c.commit?.message?.split("\n")[0] })) : commits };

const [checks, status] = await Promise.all([
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_check_runs", perPage: 50 }),
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_status" })
]);
return { checks, status };

const [checks, status] = await Promise.all([
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_check_runs", perPage: 50 }),
  tools.github.pull_request_read({ owner: "danielm5", repo: "tiffcraft", pullNumber: 46, method: "get_status" })
]);
return { checks, status };

